svg.script:
//
(function() {
  const init = () => {
    const svg = document.getElementById('piso06-svg');
    if (!svg) return;
    const cardSubdural = document.getElementById('card-subdural');
    const cardHydro = document.getElementById('card-hydro');

    const setActive = (state) => {
      svg.setAttribute('data-active', state);
    };

    if (cardSubdural) {
      cardSubdural.addEventListener('click', (e) => {
        e.stopPropagation();
        setActive('subdural');
      });
      cardSubdural.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          setActive('subdural');
        }
      });
    }

    if (cardHydro) {
      cardHydro.addEventListener('click', (e) => {
        e.stopPropagation();
        setActive('hydro');
      });
      cardHydro.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          setActive('hydro');
        }
      });
    }

    // Clicar fora ou no fundo reseta para o estado inicial
    svg.addEventListener('click', (e) => {
      if (e.target.id === 'bg-click' || e.target === svg) {
        setActive('none');
      }
    });
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
//
